  "content": "<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Notification settings</title>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&family=Source+Sans+3:wght@300..900&family=JetBrains+Mono:wght@400;500;600&display=swap"
      rel="stylesheet"
    />
    <link rel="stylesheet" href="./node_modules/@taproot-ds/tokens/dist/css/tokens.css" />
    <link rel="stylesheet" href="./node_modules/@taproot-ds/tokens/dist/css/base.css" />
    <style>
      main {
        max-width: 36rem;
        margin: 0 auto;
        padding: var(--ds-primitives-space-8) var(--ds-primitives-space-4);
      }
      .panel {
        display: flex;
        flex-direction: column;
        gap: var(--ds-primitives-space-6);
        padding: var(--ds-primitives-space-6);
        background: var(--ds-semantic-color-background-surface);
        border: var(--ds-semantic-border-width) solid var(--ds-semantic-color-border-subtle);
        border-radius: var(--ds-semantic-radius-surface);
        box-shadow: var(--ds-semantic-elevation-sm);
      }
      .intro {
        margin: 0 0 var(--ds-primitives-space-6);
        color: var(--ds-semantic-color-foreground-muted);
      }
    </style>
    <script type="module" src="./node_modules/@taproot-ds/web-components/src/index.js"></script>
  </head>
  <body>
    <main>
      <h1>Notification settings</h1>
      <p class="intro">Changes apply immediately.</p>

      <section class="panel" aria-label="Notifications">
        <ds-switch
          id="email-notifications"
          label="Email notifications"
          hint="Get updates sent to your inbox."
          checked
        ></ds-switch>

        <ds-switch
          id="push-notifications"
          label="Push notifications"
          hint="Get alerts on this device."
        ></ds-switch>

        <ds-slider
          id="sound-volume"
          label="Notification sound volume"
          min="0"
          max="100"
          step="1"
          value="50"
        ></ds-slider>
      </section>
    </main>

    <script type="module">
      const STORAGE_KEY = "notification-settings";

      function load() {
        try {
          return JSON.parse(localStorage.getItem(STORAGE_KEY)) ?? {};
        } catch {
          return {};
        }
      }

      function save(patch) {
        const next = { ...load(), ...patch };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      }

      await Promise.all([
        customElements.whenDefined("ds-switch"),
        customElements.whenDefined("ds-slider"),
      ]);

      const email = document.getElementById("email-notifications");
      const push = document.getElementById("push-notifications");
      const volume = document.getElementById("sound-volume");

      // Restore saved settings (programmatic changes fire no events).
      const saved = load();
      if (typeof saved.email === "boolean") email.checked = saved.email;
      if (typeof saved.push === "boolean") push.checked = saved.push;
      if (typeof saved.volume === "number") volume.value = saved.volume;

      // Apply each switch immediately; on failure, restore and explain.
      function bindSwitch(el, key) {
        el.addEventListener("change", () => {
          const value = el.checked;
          try {
            save({ [key]: value });
            el.removeAttribute("error");
          } catch {
            el.checked = !value;
            el.setAttribute("error", "Couldn't save this setting. Try again.");
          }
        });
      }

      bindSwitch(email, "email");
      bindSwitch(push, "push");

      volume.addEventListener("change", () => {
        try {
          save({ volume: Number(volume.value) });
          volume.removeAttribute("error");
        } catch {
          volume.setAttribute("error", "Couldn't save the volume. Try again.");
        }
      });
    </script>
  </body>
</html>
